def countRoutesFewObstacles(m, n, obstacles):
    MOD = 10 ** 9 + 7
    size = m + n
    fact = [1] * (size + 1)
    for i in range(1, size + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (size + 1)
    inv[size] = pow(fact[size], MOD - 2, MOD)
    for i in range(size, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def ways(dr, dc):
        if dr < 0 or dc < 0:
            return 0
        return fact[dr + dc] * inv[dr] % MOD * inv[dc] % MOD

    pts = sorted(tuple(o) for o in obstacles)
    if (0, 0) in pts or (m - 1, n - 1) in pts:
        return 0
    pts.append((m - 1, n - 1))
    f = []
    for i, (r, c) in enumerate(pts):
        v = ways(r, c)
        for j in range(i):
            rj, cj = pts[j]
            if cj <= c:
                v -= f[j] * ways(r - rj, c - cj)
        f.append(v % MOD)
    return f[-1]
